func TestSprintResourceNoRecursion(t *testing.T) {
	t.Parallel()

	r := &dummyResource{
		Name: String("test-resource"),
		Nested: &dummyNestedResource{
			Title:   String("sub"),
			Count:   Int64(7),
			Enabled: Bool(true),
		},
	}

	// Calling r.String() invokes SprintResource(r); verify no infinite recursion.
	str := r.String()
	if !strings.Contains(str, `"name": "test-resource"`) {
		t.Errorf("SprintResource output missing expected field: %s", str)
	}
	if !strings.Contains(str, "\n") {
		t.Errorf("expected multiline output from SprintResource, got %q", str)
	}

	compact := SprintResourceCompact(r)
	if !strings.Contains(compact, `"name":"test-resource"`) {
		t.Errorf("SprintResourceCompact output missing expected field: %s", compact)
	}
	if strings.Contains(compact, "\n") {
		t.Errorf("expected single-line output from SprintResourceCompact, got %q", compact)
	}

	// Verify fallback on unmarshalable types also avoids calling String() (no recursion).
	bad := &unmarshalableResource{
		Name: "bad",
		Ch:   make(chan int),
	}
	badStr := fmt.Sprint(bad)
	if !strings.Contains(badStr, "unmarshalableResource") {
		t.Errorf("expected Go-syntax fallback for unmarshalableResource, got %q", badStr)
	}
	badCompact := SprintResourceCompact(bad)
	if !strings.Contains(badCompact, "unmarshalableResource") {
		t.Errorf("expected Go-syntax fallback for SprintResourceCompact, got %q", badCompact)
	}
}

func TestBackoff(t *testing.T) {
	t.Parallel()

	bo := NewBackoff()
	if bo.InitialInterval != BackoffInitialInterval {
		t.Errorf("NewBackoff().InitialInterval = %v, want %v", bo.InitialInterval, BackoffInitialInterval)
	}
	if bo.MaxInterval != BackoffMaxInterval {
		t.Errorf("NewBackoff().MaxInterval = %v, want %v", bo.MaxInterval, BackoffMaxInterval)
	}

	// First RetryAfter should be within [0.5 * InitialInterval, 1.5 * InitialInterval].
	d1 := bo.RetryAfter(nil)
	min1 := time.Duration(0.5 * float64(BackoffInitialInterval))
	max1 := time.Duration(1.5 * float64(BackoffInitialInterval))
	if d1 < min1 || d1 > max1 {
		t.Errorf("first RetryAfter = %v, want in [%v, %v]", d1, min1, max1)
	}

	// Custom options and clamping at maxInterval.
	initial := 100 * time.Millisecond
	maxInt := 200 * time.Millisecond
	custom := NewBackoffWithOptions(initial, maxInt)

	// Step 1: current = 100ms -> [50ms, 150ms], next current = 150ms
	s1 := custom.RetryAfter(nil)
	if s1 < 50*time.Millisecond || s1 > 150*time.Millisecond {
		t.Errorf("step 1 RetryAfter = %v, want in [50ms, 150ms]", s1)
	}

	// Step 2: current = 150ms -> [75ms, 225ms], next current clamped to 200ms
	s2 := custom.RetryAfter(nil)
	if s2 < 75*time.Millisecond || s2 > 225*time.Millisecond {
		t.Errorf("step 2 RetryAfter = %v, want in [75ms, 225ms]", s2)
	}

	// Step 3+: current stays clamped at 200ms -> [100ms, 300ms], even after many iterations (no overflow).
	for i := 0; i < 1000; i++ {
		sn := custom.RetryAfter(nil)
		if sn < 100*time.Millisecond || sn > 300*time.Millisecond {
			t.Fatalf("iteration %d: RetryAfter = %v, want in [100ms, 300ms]", i, sn)
		}
	}

	// Zero-value Backoff and NewBackoffWithOptions(0, 0) fall back to defaults.
	zeroOpts := NewBackoffWithOptions(0, 0)
	if d := zeroOpts.RetryAfter(nil); d < min1 || d > max1 {
		t.Errorf("NewBackoffWithOptions(0, 0) RetryAfter = %v, want in [%v, %v]", d, min1, max1)
	}
	zeroStruct := &Backoff{}
	if d := zeroStruct.RetryAfter(nil); d < min1 || d > max1 {
		t.Errorf("(&Backoff{}).RetryAfter = %v, want in [%v, %v]", d, min1, max1)
	}
}
